"""Stock availability for the web shop."""

import unittest

# An unpaid reservation stops holding units once it is this old, in seconds.
UNPAID_TTL_S = 300


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _is_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def available(stock, reservations, now_s):
    """Return how many units can still be sold.

    stock        -- units on the shelf (int, >= 0)
    reservations -- iterable of dicts with keys 'qty', 'created_s' and 'paid'
    now_s        -- current time in seconds, on the same clock as 'created_s'

    Paid reservations hold their units and never expire. Unpaid reservations
    hold their units until they are UNPAID_TTL_S seconds old. At exactly that
    age they are expired. A missing 'paid' key counts as unpaid. A reservation
    with 'created_s' in the future (clock skew) is active. The result is never
    less than 0.

    All inputs are checked before any calculation. Invalid input raises
    TypeError or ValueError. The inputs are not modified.
    """
    if not _is_int(stock):
        raise TypeError("stock must be an int")
    if stock < 0:
        raise ValueError("stock must not be negative")
    if not _is_number(now_s):
        raise TypeError("now_s must be a number")
    if reservations is None:
        raise TypeError("reservations must be an iterable of dicts")

    checked = []
    for index, reservation in enumerate(reservations):
        if not isinstance(reservation, dict):
            raise TypeError(f"reservation {index} must be a dict")
        if "qty" not in reservation:
            raise ValueError(f"reservation {index} is missing 'qty'")
        if "created_s" not in reservation:
            raise ValueError(f"reservation {index} is missing 'created_s'")

        qty = reservation["qty"]
        created_s = reservation["created_s"]
        paid = reservation.get("paid", False)

        if not _is_int(qty):
            raise TypeError(f"reservation {index}: 'qty' must be an int")
        if qty < 0:
            raise ValueError(f"reservation {index}: 'qty' must not be negative")
        if not _is_number(created_s):
            raise TypeError(f"reservation {index}: 'created_s' must be a number")
        if not isinstance(paid, bool):
            raise TypeError(f"reservation {index}: 'paid' must be a bool")

        checked.append((qty, created_s, paid))

    held = 0
    for qty, created_s, paid in checked:
        if paid or now_s - created_s < UNPAID_TTL_S:
            held += qty

    return max(0, stock - held)


class AvailableTests(unittest.TestCase):
    NOW = 10_000

    def res(self, qty, age, paid=False):
        return {"qty": qty, "created_s": self.NOW - age, "paid": paid}

    def test_no_reservations(self):
        self.assertEqual(available(10, [], self.NOW), 10)

    def test_unpaid_inside_ttl_holds(self):
        self.assertEqual(available(10, [self.res(3, 299)], self.NOW), 7)

    def test_unpaid_outside_ttl_released(self):
        self.assertEqual(available(10, [self.res(3, 301)], self.NOW), 10)

    def test_unpaid_exact_boundary_is_expired(self):
        self.assertEqual(available(10, [self.res(3, UNPAID_TTL_S)], self.NOW), 10)

    def test_paid_never_expires(self):
        self.assertEqual(available(10, [self.res(4, 1_000_000, paid=True)], self.NOW), 6)

    def test_missing_paid_counts_as_unpaid(self):
        fresh = {"qty": 2, "created_s": self.NOW - 10}
        old = {"qty": 5, "created_s": self.NOW - 400}
        self.assertEqual(available(10, [fresh, old], self.NOW), 8)

    def test_mixed(self):
        reservations = [
            self.res(2, 10),
            self.res(3, 500),
            self.res(1, 500, paid=True),
        ]
        self.assertEqual(available(10, reservations, self.NOW), 7)

    def test_overbooking_clamps_to_zero(self):
        reservations = [self.res(8, 10), self.res(5, 0, paid=True)]
        self.assertEqual(available(10, reservations, self.NOW), 0)

    def test_future_created_s_is_active(self):
        self.assertEqual(available(10, [self.res(3, -60)], self.NOW), 7)

    def test_inputs_not_mutated(self):
        reservations = [self.res(2, 10), {"qty": 1, "created_s": self.NOW}]
        snapshot = [dict(r) for r in reservations]
        available(10, reservations, self.NOW)
        self.assertEqual(reservations, snapshot)

    def test_negative_stock_rejected(self):
        with self.assertRaises(ValueError):
            available(-1, [], self.NOW)

    def test_negative_qty_rejected(self):
        with self.assertRaises(ValueError):
            available(10, [self.res(-1, 10)], self.NOW)

    def test_invalid_reservation_rejected_before_calculation(self):
        reservations = [self.res(2, 10), {"qty": 1}]
        with self.assertRaises(ValueError):
            available(10, reservations, self.NOW)

    def test_bad_types_rejected(self):
        with self.assertRaises(TypeError):
            available("10", [], self.NOW)
        with self.assertRaises(TypeError):
            available(10, [{"qty": "1", "created_s": 0}], self.NOW)
        with self.assertRaises(TypeError):
            available(10, [{"qty": 1, "created_s": 0, "paid": "yes"}], self.NOW)
        with self.assertRaises(TypeError):
            available(10, None, self.NOW)


if __name__ == "__main__":
    unittest.main()
